CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, email TEXT NOT NULL UNIQUE, pass_hash TEXT NOT NULL, first_name TEXT NOT NULL, last_name TEXT NOT NULL, branch TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'pending', consent_at TEXT, created_at TEXT NOT NULL, approved_at TEXT);
CREATE TABLE IF NOT EXISTS userdata (user_id INTEGER PRIMARY KEY, rev INTEGER NOT NULL DEFAULT 1, n INTEGER NOT NULL DEFAULT 0, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS chunks (user_id INTEGER NOT NULL, idx INTEGER NOT NULL, part TEXT NOT NULL, PRIMARY KEY (user_id, idx));
CREATE TABLE IF NOT EXISTS sessions (tok TEXT PRIMARY KEY, user_id INTEGER NOT NULL, exp INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS attempts (id INTEGER PRIMARY KEY AUTOINCREMENT, k TEXT NOT NULL, ts INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS attempts_k ON attempts(k, ts);
ALTER TABLE users ADD COLUMN last_login TEXT;
ALTER TABLE users ADD COLUMN login_count INTEGER NOT NULL DEFAULT 0;
ALTER TABLE users ADD COLUMN last_save TEXT;
ALTER TABLE users ADD COLUMN students_count INTEGER NOT NULL DEFAULT 0;
CREATE TABLE IF NOT EXISTS audit (id INTEGER PRIMARY KEY AUTOINCREMENT, ts TEXT NOT NULL, actor TEXT NOT NULL, action TEXT NOT NULL, target_id INTEGER, detail TEXT, country TEXT);
CREATE INDEX IF NOT EXISTS audit_ts ON audit(ts);
CREATE TABLE IF NOT EXISTS family_leads (id INTEGER PRIMARY KEY AUTOINCREMENT, created_at TEXT NOT NULL, lang TEXT, name TEXT NOT NULL, phone TEXT NOT NULL, gender TEXT, age TEXT, track TEXT, results TEXT, summary TEXT, country TEXT, handled INTEGER NOT NULL DEFAULT 0);
